            "niv": "Now a man of God came to Eli and said to him, \"This is what the Lord says: 'Did I not clearly reveal myself to your father's house when they were in Egypt under Pharaoh?",
            "esv": "And there came a man of God to Eli and said to him, “Thus the LORD has said, ‘Did Iindeed reveal myself to the house of your father when they were in Egypt subject to the house of Pharaoh?"
