            "asv": "Now therefore, I pray thee, let my lord the king hear the words of his servant. If it be Jehovah that hath stirred thee up against me, let him accept an offering: but if it be the children of men, cursed be they before Jehovah: for they have driven me out this day that I should not cleave unto the inheritance of Jehovah, saying, Go, serve other gods.",
            "niv": "Now let my lord the king listen to his servant's words. If the Lord has incited you against me, then may he accept an offering. If, however, men have done it, may they be cursed before the Lord ! They have now driven me from my share in the Lord 's inheritance and have said, 'Go, serve other gods.'",
            "esv": "Now therefore let my lord the king hear the words of his servant. If it is the LORD who has stirred you up against me, may he accept an offering, but if it is men, may they be cursed before the LORD, for they have driven me out this day that Ishould have no share in the heritage of the LORD, saying, ‘Go, serve other gods.’"
